def turn_acceptance_score_reason(turn: Any) -> str:
    """Return why a turn is diagnostic-only for acceptance scoring."""

    if str(_turn_field(turn, "speaker") or "") == "pilot":
        return "pilot_origin"
    if str(_turn_field(turn, "target") or "") != "ownship":
        return "non_ownship"
    expected_radio_artifact = _turn_field(turn, "expected_radio_artifact")
    if (
        str(_turn_field(expected_radio_artifact, "reason") or "")
        == "source_expected_speech_missing"
    ):
        return "source_expected_speech_missing"
    return ""

NON_CANONICAL_SCENARIO_IDS: Final[frozenset[str]] = frozenset(
    {"batc_operator_practice_v1"}
)

def corpus_for_scenario_id(scenario_id: str) -> str:
    if scenario_id.startswith("batc_parameterized__"):
        return "holdout"
    return "a2" if scenario_id.startswith("pe_") else "a1"

